# Диктанты: 3 предложения на неделю (венгерский, русский)
DICT = {
1:[("Jó napot kívánok!","Добрый день!"),("A nevem Kirill.","Меня зовут Кирилл."),("Köszönöm, nem értem.","Спасибо, я не понимаю.")],
2:[("Permben lakom.","Я живу в Перми."),("Liszvában születtem.","Я родился в Лысьве."),("A nagyapám Csománfalván született.","Мой дед родился в Чумалёве.")],
3:[("Történész vagyok.","Я историк."),("Egy kicsit beszélek magyarul.","Я немного говорю по-венгерски."),("Oroszul és angolul beszélek.","Я говорю по-русски и по-английски.")],
4:[("Az apám negyvennyolc éves.","Моему отцу сорок восемь лет."),("A dédapám magyar állampolgár volt.","Мой прадед был венгерским гражданином."),("A családom Liszvában él.","Моя семья живёт в Лысьве.")],
5:[("Hogy van? Köszönöm, jól.","Как вы? Спасибо, хорошо."),("Nincs autóm, de van lakásom.","У меня нет машины, но есть квартира."),("Ez egy régi könyv.","Это старая книга.")],
6:[("Tudok írni és olvasni magyarul.","Я умею писать и читать по-венгерски."),("Nem tudok még jól beszélni.","Я ещё не умею хорошо говорить."),("Ez nehéz, de érdekes.","Это трудно, но интересно.")],
7:[("Reggel hétkor kelek fel.","Я встаю в семь утра."),("Hétfőn és szerdán tanulok.","В понедельник и среду я учусь."),("Hány óra van? Fél kilenc.","Который час? Половина девятого.")],
8:[("Busszal megyek a munkába.","Я еду на работу на автобусе."),("A barátommal utazom Budapestre.","Я еду в Будапешт с другом."),("Honnan jön? Ukrajnából.","Откуда вы? Из Украины.")],
9:[("Menjen egyenesen, aztán jobbra.","Идите прямо, потом направо."),("Csománfalva Técső mellett van.","Чумалёво рядом с Тячевом."),("Permből vonattal megyek Liszvába.","Из Перми в Лысьву я еду поездом.")],
10:[("Reggel kávét iszom.","Утром я пью кофе."),("A nagyapám gulyást főz.","Мой дед варит гуляш."),("Éhes vagyok, kérek egy levest.","Я голоден, прошу суп.")],
11:[("Mennyibe kerül egy kiló alma?","Сколько стоит килограмм яблок?"),("Két darabot kérek.","Прошу две штуки."),("Ez túl drága, köszönöm.","Это слишком дорого, спасибо.")],
12:[("Látom a házat.","Я вижу дом."),("Keresek egy fekete kabátot.","Я ищу чёрное пальто."),("Szeretem a magyar nyelvet.","Я люблю венгерский язык.")],
13:[("A nagyapám magas és erős ember.","Мой дед высокий и сильный человек."),("Az apám idősebb, mint az anyám.","Мой отец старше моей матери."),("Hasonlítok a nagyapámra.","Я похож на деда.")],
14:[("Nekem kell az állampolgárság.","Мне нужно гражданство."),("Be kell nyújtani a kérelmet.","Нужно подать заявление."),("Azért tanulok, mert fontos.","Я учусь, потому что это важно.")],
15:[("A dédapámnak volt egy háza Csománfalván.","У моего прадеда был дом в Чумалёве."),("Nekem nincs autóm.","У меня нет машины."),("A dédapám cipész volt.","Мой прадед был сапожником.")],
16:[("A nagyapám ezerkilencszázötvenegyben született.","Мой дед родился в 1951 году."),("A dédapám Franciaországban dolgozott.","Мой прадед работал во Франции."),("Tavaly kezdtem tanulni magyarul.","В прошлом году я начал учить венгерский.")],
17:[("A nagyapám tengerész volt, aztán favágó lett.","Мой дед был моряком, потом стал лесорубом."),("Az Urálba költözött.","Он переехал на Урал."),("A szülei Csománfalván maradtak.","Его родители остались в Чумалёве.")],
18:[("Reggel elmegyek otthonról.","Утром я ухожу из дома."),("Megnézem a dokumentumokat.","Я посмотрю документы."),("Nem olvastam el a levelet.","Я не прочитал письмо.")],
19:[("Ismerem a nagyapám faluját.","Я знаю село моего деда."),("Látok egy templomot, és látom a templomot.","Я вижу церковь, и я вижу эту церковь."),("Tudom, hogy ez nehéz.","Я знаю, что это трудно.")],
20:[("Kedves rokonom, üdvözöllek Permből!","Дорогой родственник, приветствую из Перми!"),("Szeretnélek meglátogatni.","Я хотел бы тебя навестить."),("Hiányzik a család.","Я скучаю по семье.")],
21:[("A dédapámat Babics Fjodornak hívták.","Моего прадеда звали Фёдор Бабич."),("A dédanyám leánykori neve Olekszisenec.","Девичья фамилия прабабушки Олексишенец."),("A családfám öt nemzedékre nyúlik vissza.","Моё родословное древо уходит на пять поколений.")],
22:[("Április tizenkettedikén születtem.","Я родился двенадцатого апреля."),("Az apám március tizenhetedikén született.","Мой отец родился семнадцатого марта."),("A ház a templom mögött van.","Дом за церковью.")],
23:[("Régen a dédapám a földeken dolgozott.","Раньше прадед работал в поле."),("A családom ortodox vallású volt.","Моя семья была православной."),("Az anyakönyvet a levéltárban találtam.","Метрическую книгу я нашёл в архиве.")],
24:[("Csománfalva Kárpátalján van, Técső mellett.","Чумалёво в Закарпатье, рядом с Тячевом."),("Ebben a faluban született a nagyapám.","В этом селе родился мой дед."),("Magyarországon még nem jártam.","В Венгрии я ещё не был.")],
25:[("Jövőre Magyarországra fogok utazni.","В следующем году я поеду в Венгрию."),("Szeretnék Európában dolgozni.","Я хотел бы работать в Европе."),("Ha megkapom az állampolgárságot, meglátogatom Csománfalvát.","Если получу гражданство, навещу Чумалёво.")],
26:[("Jó napot kívánok, Babics Kirill vagyok.","Добрый день, я Кирилл Бабич."),("Honosítási kérelmet szeretnék benyújtani.","Я хотел бы подать заявление о натурализации."),("Legyen szíves, ismételje meg!","Будьте добры, повторите!")],
27:[("A dédapám, aki Csománfalván született, magyar állampolgár volt.","Мой прадед, который родился в Чумалёве, был венгерским гражданином."),("Azért szeretnék magyar állampolgár lenni, mert a felmenőim magyarok voltak.","Я хочу стать венгерским гражданином, потому что мои предки были венграми."),("Tudom, hogy a nyelv fontos.","Я знаю, что язык важен.")],
28:[("Még nem jártam Magyarországon.","Я ещё не бывал в Венгрии."),("Minden nap szoktam tanulni.","Я обычно учусь каждый день."),("Sokat változott a családom élete.","Жизнь моей семьи сильно изменилась.")],
29:[("Kérem, beszéljen lassabban!","Пожалуйста, говорите медленнее!"),("Mondja el, honnan származik!","Расскажите, откуда вы родом!"),("Ne aggódjon, van időnk.","Не беспокойтесь, у нас есть время.")],
30:[("Azt javaslom, hogy gyűjtse össze az okmányokat.","Советую собрать документы."),("Fontos, hogy minden nap gyakorolj.","Важно, чтобы ты практиковался каждый день."),("Azt akarom, hogy sikerüljön.","Я хочу, чтобы получилось.")],
31:[("Szerintem a magyar nyelv logikus, de nehéz.","По-моему, венгерский логичен, но труден."),("A legnehezebb a határozott ragozás.","Самое трудное — определённое спряжение."),("Nagyon tetszik a hangzása.","Мне очень нравится его звучание.")],
32:[("Röviden elmondom a családom történetét.","Коротко расскажу историю моей семьи."),("Ha jól emlékszem, a dédapám ezerkilencszázháromban született.","Если я правильно помню, прадед родился в 1903 году."),("Nőtlen vagyok, Permben lakom.","Я холост, живу в Перми.")],
33:[("A trianoni békeszerződés után Kárpátalja Csehszlovákiához került.","После Трианонского договора Закарпатье отошло к Чехословакии."),("Ezerkilencszázharminckilencben a terület visszakerült Magyarországhoz.","В 1939 году территория вернулась Венгрии."),("A dédapám ruszin volt, és görögkatolikus.","Мой прадед был русином и греко-католиком.")],
34:[("Elhoztam a nagyapám születési anyakönyvi kivonatát.","Я принёс свидетельство о рождении деда."),("A dokumentum igazolja, hogy a nagyapám Csománfalván született.","Документ подтверждает, что дед родился в Чумалёве."),("A fordítás hiteles, apostille-lal.","Перевод заверенный, с апостилем.")],
35:[("Adatelemzőként dolgozom egy nagy cégnél.","Я работаю аналитиком данных в большой фирме."),("A bölcsészkaron történelmet tanultam.","На гуманитарном факультете я изучал историю."),("Levéltári forrásokat kutatok.","Я исследую архивные источники.")],
36:[("Jelenleg Oroszországban élek.","Сейчас я живу в России."),("Szeretnék gyakrabban Magyarországra utazni.","Я хотел бы чаще ездить в Венгрию."),("Egyelőre nem tervezek átköltözni.","Пока я не планирую переезжать.")],
37:[("Hát, szóval, a dédapám cipész volt.","Ну, так вот, мой прадед был сапожником."),("Tessék? Hogy mondta?","Простите? Как вы сказали?"),("Akarom mondani, a nagyapám, nem az apám.","То есть, дед, а не отец.")],
38:[("Egy kicsit izgulok, de felkészültem.","Я немного волнуюсь, но подготовился."),("Ha hibázom, kérem, javítson ki.","Если я ошибусь, пожалуйста, поправьте."),("Lassan, de érthetően beszélek.","Я говорю медленно, но понятно.")],
39:[("A hírek szerint holnap esik az eső.","По новостям, завтра будет дождь."),("A kormány új törvényt jelentett be.","Правительство объявило новый закон."),("Budapesten tizenöt fok van.","В Будапеште пятнадцать градусов.")],
40:[("Tisztelt Konzul Úr, köszönöm a lehetőséget.","Уважаемый господин консул, благодарю за возможность."),("Mellékelem az összes okmányt.","Прилагаю все документы."),("Várom a válaszát, tisztelettel.","Жду вашего ответа, с уважением.")],
41:[("A gyenge pontom a határozott ragozás.","Моё слабое место — определённое спряжение."),("Átismétlem a névutókat és a dátumokat.","Я повторю послелоги и даты."),("Ez a rag mély hangrendű szóhoz illik.","Этот суффикс подходит к слову заднего ряда.")],
42:[("Elnézést, visszakérdezhetek?","Простите, могу переспросить?"),("Röviden és tömören: a felmenőim Csománfalváról származnak.","Кратко: мои предки родом из Чумалёва."),("Senki sem maradt a faluban a rokonaim közül.","Никто из моих родственников не остался в селе.")],
43:[("Fogadom, hogy Magyarországot hazámnak tekintem.","Клянусь считать Венгрию своей родиной."),("Köszönöm, megérte a munkát.","Спасибо, это стоило труда."),("Büszke vagyok a felmenőimre.","Я горжусь своими предками.")],
}
# Встроенные упражнения (без Claude), недели 1–8: cloze с вариантами
EX = {
1:[("Jó ___ kívánok!",["napot","nap","napok"],"napot","Фиксированная формула приветствия: jó napot kívánok."),("A ___ Kirill.",["nevem","neved","neve"],"nevem","-m = мой: nevem «моё имя»."),("Nem ___.",["értem","érted","érti"],"értem","1 л. ед. ч.: értem «я понимаю»."),("Буква «s» читается как",["ш","с","з"],"ш","s = ш, sz = с."),("Ударение в венгерском",["всегда на первом слоге","на последнем","свободное"],"всегда на первом слоге","Исключений нет.")],
2:[("Perm___ lakom.",["ben","ban","on"],"ben","Perm: гласный e, передний ряд → -ben."),("Liszva___ születtem.",["ban","ben","be"],"ban","Liszva: задний ряд → -ban."),("A nagyapám Csománfalv___ született.",["án","en","ban"],"án","Венгерские сёла на -falva берут -n: Csománfalván."),("Én diák ___.",["vagyok","vagy","van"],"vagyok","1 л.: vagyok."),("___ laksz?",["Hol","Hova","Honnan"],"Hol","Hol? = где (место без движения).")],
3:[("Magyar___ beszélek egy kicsit.",["ul","ül","on"],"ul","magyar: задний ряд → -ul."),("Német___ nem beszélek.",["ül","ul","en"],"ül","német: передний ряд → -ül."),("Történész ___.",["vagyok","van","vagy"],"vagyok","Профессия с vagyok, без артикля."),("Liszv___ ember vagyok.",["ai","i","ás"],"ai","Liszva + -i → liszvai (a→ai)."),("Egy cégnél ___.",["dolgozom","dolgozik","dolgozol"],"dolgozom","dolgozik — ikes-глагол: 1 л. -om.")],
4:[("Az apám negyvennyolc ___.",["éves","év","évek"],"éves","Возраст: X éves."),("A nagyapám ___ Csománfalván.",["született","születtem","születik"],"született","3 л. прошедшее."),("Ez a ___ apja.",["nagyapám","nagyapja","nagyapám"],"nagyapám","apja = его отец; nagyapám = мой дед."),("Hány ___ a nagyapád?",["éves","év","évesek"],"éves","Hány éves? = сколько лет?"),("Van ___?",["testvéred","testvér","testvérem"],"testvéred","Вопрос «у тебя есть брат/сестра?»: -d = твой.")],
5:[("___ autóm.",["Nincs","Nem","Nincsenek"],"Nincs","Отсутствие предмета: nincs."),("Ez ___ régi könyv.",["egy","a","az"],"egy","Неопределённый артикль."),("Hogy ___, konzul úr?",["van","vagy","vagyok"],"van","Вежливая форма = 3 лицо."),("___ asztal nagy.",["Az","A","Egy"],"Az","Перед гласной: az."),("Itt ___ a telefon.",["van","nincs","vagyok"],"van","Утверждение о месте: van. Отрицание было бы nincs itt, «nem van» не существует."),],
6:[("Tudok ___ magyarul.",["olvasni","olvas","olvasok"],"olvasni","После tud — инфинитив -ni."),("Nem ___ még jól beszélni.",["tudok","tud","tudni"],"tudok","Модальный глагол спрягается, смысловой в инфинитиве."),("___ a könyv érdekes.",["Ez","Ezek","Az"],"Ez","Указательное + артикль: ez a könyv."),("Itt ___ parkolni.",["lehet","tud","kell"],"lehet","lehet = можно (безлично)."),("___ tanulni akarok.",["Magyarul","Magyar","Magyarok"],"Magyarul","На каком языке → -ul.")],
7:[("Reggel hét___ kelek fel.",["kor","ban","ra"],"kor","Время «в N часов»: -kor."),("Hétfő___ tanulok.",["n","ben","kor"],"n","Дни недели: -n (hétfőn), кроме vasárnap."),("___ tanulsz?",["Mikor","Mennyi","Hány"],"Mikor","Mikor? = когда?"),("Fél ___ van.",["kilenc","nyolc","kilences"],"kilenc","Fél kilenc = половина девятого (8:30)."),("Este tíz___ fekszem le.",["kor","ben","n"],"kor","-kor для часов.")],
8:[("Busz___ megyek a munkába.",["szal","val","vel"],"szal","-val ассимилируется: busz+val → busszal."),("A barátom___ utazom.",["mal","val","vel"],"mal","barátom + val → barátommal."),("___ jössz? Ukrajnából.",["Honnan","Hol","Hova"],"Honnan","Откуда → Honnan, ответ -ból/-ből."),("Budapest___ megyek.",["re","ra","ba"],"re","Венгерские города чаще -ra/-re: Budapestre."),("A bolt___ vagyok.",["ban","ba","ból"],"ban","Нахожусь в магазине: -ban.")],
}
